198	+/// Format at most 8 names, each cut to 64 chars and Debug-escaped.
199	+fn format_blank_names(names: &[String]) -> String {
200	+    const MAX_NAMES: usize = 8;
201	+    const MAX_CHARS: usize = 64;
202	+    let mut out = names
203	+        .iter()
204	+        .take(MAX_NAMES)
205	+        .map(|n| format!("{:?}", n.chars().take(MAX_CHARS).collect::<String>()))
206	+        .collect::<Vec<_>>()
207	+        .join(", ");
208	+    if names.len() > MAX_NAMES {
209	+        out.push_str(&format!(", and {} more", names.len() - MAX_NAMES));
210	+    }
211	+    out
